ers as $o): ?><tr><td class="reference-cell"><?=e($o['order_code'])?></td><td><?=e($o['service'])?></td><td><?=e(ucwords(str_replace('_',' ',$o['status'])))?></td><td><?= $o['quote_amount']!==null ? e(number_format((float)$o['quote_amount'],2)) : '—' ?></td><td><?=e(ucwords(str_replace('_',' ',$o['payment_status']??'unpaid')))?></td><td><?=e(date('d M Y',strtotime($o['created_at'])))?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><p class="admin-footnote">Payment will only show as successful after verified confirmation from the payment provider.</p></main></body></html>